"""Phase 2A tests generated by the fleet review round: OpenAI's
adversarial findings (audit re-seal laundering, revocation vs saved
copies, insert-only write, CLI existence oracle, URL secrets in
metadata) and DeepSeek's adversarial edge cases (malformed tokens,
colon scopes, audit reorder/truncation). Every test states the
finding it closes."""

import base64
import json
import os
import subprocess
import sys

import pytest

from mykey import MyKey, make_entry
import agents
from agents import (AgentAuthError, AgentScopeError, enroll_agent,
                    open_agent_session, reset_audit, revoke_agent,
                    verify_audit)

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
MASTER = "correct horse battery staple"


def _vault(tmp):
    v = MyKey(MASTER, vault_file=os.path.join(tmp, "vault.mykey"))
    v.unlock()
    v.add_entry(make_entry(service="github", username="me", password="gh-secret",
                           url="https://user:pw@github.com/x?token=abc#frag",
                           tags=["dev"]))
    return v


def test_audit_mismatch_is_never_resealed(tmp_path):
    """OpenAI F1: a tampered chain must not be laundered by the next
    auth attempt — no append, no re-seal, file byte-identical."""
    t = str(tmp_path)
    v = _vault(t)
    token = enroll_agent(v, "wright", ["list"])
    open_agent_session(v.vault_file, token)
    audit_file = v.vault_file + ".audit.jsonl"
    with open(audit_file, "rb") as f:
        before = f.read()
    lines = before.decode().splitlines()
    rec = json.loads(lines[0])
    rec["result"] = "deny"
    lines[0] = json.dumps(rec)
    with open(audit_file, "w") as f:
        f.write("\n".join(lines) + "\n")
    with pytest.raises(AgentAuthError):
        open_agent_session(v.vault_file, token)
    with open(audit_file, "rb") as f:
        assert f.read().decode().splitlines()[0] == lines[0]  # untouched
    human = MyKey(MASTER, vault_file=v.vault_file)
    human.unlock()
    assert human._audit_head != ""  # seal unchanged, still points at truth
    assert verify_audit(v.vault_file, expected_head=human._audit_head)["ok"] is False


def test_audit_reset_archives_and_recovers(tmp_path):
    t = str(tmp_path)
    v = _vault(t)
    token = enroll_agent(v, "wright", ["list"])
    audit_file = v.vault_file + ".audit.jsonl"
    with open(audit_file, "a") as f:
        f.write('{"forged": true}\n')
    archive = reset_audit(v)
    assert archive and os.path.exists(archive)  # suspect log preserved
    session = open_agent_session(v.vault_file, token)  # works again
    assert session.list_metadata()
    assert verify_audit(v.vault_file, expected_head=_head(v))["ok"]


def _head(v):
    h = MyKey(MASTER, vault_file=v.vault_file)
    h.unlock()
    return h._audit_head


def test_rotate_vault_key_kills_agents_and_recovery(tmp_path):
    """OpenAI F3: rotation is the cryptographic answer — every old
    slot dies. A previously SAVED vault copy still opens with the old
    token (no design can claw back copies); that truth is asserted
    here and documented, not hidden."""
    t = str(tmp_path)
    v = _vault(t)
    token = enroll_agent(v, "wright", ["list"])
    saved_copy = os.path.join(t, "saved-copy.mykey")
    with open(v.vault_file, "rb") as src, open(saved_copy, "wb") as dst:
        dst.write(src.read())
    result = v.rotate_vault_key()
    assert result["agents_dropped"] == 1
    with pytest.raises(AgentAuthError):
        open_agent_session(v.vault_file, token)
    human = MyKey(MASTER, vault_file=v.vault_file)
    human.unlock()
    assert human.list_entries()[0]["service"] == "github"  # payload intact
    assert not os.path.exists(v.vault_file + ".bak")  # no stale backup
    clone = open_agent_session(saved_copy, token)  # copy cannot be clawed back
    assert clone.agent_id == "wright"


def test_revoke_syncs_backup_so_copied_backup_is_dead(tmp_path):
    """The rolling .bak must not keep a revoked agent's slot alive."""
    t = str(tmp_path)
    v = _vault(t)
    token = enroll_agent(v, "wright", ["list"])
    revoke_agent(v, "wright")
    bak = v.vault_file + ".bak"
    assert os.path.exists(bak)
    clone_path = os.path.join(t, "from-backup.mykey")
    with open(bak, "rb") as src, open(clone_path, "wb") as dst:
        dst.write(src.read())
    with pytest.raises(AgentAuthError):
        open_agent_session(clone_path, token)


def test_agent_write_is_insert_only(tmp_path):
    """OpenAI F5: a write-scoped agent cannot overwrite an entry."""
    t = str(tmp_path)
    v = _vault(t)
    token = enroll_agent(v, "writer", ["write"])
    s = open_agent_session(v.vault_file, token)
    with pytest.raises(Exception):
        s.add_entry({"service": "github", "username": "me",
                     "password": "planted"})
    human = MyKey(MASTER, vault_file=v.vault_file)
    human.unlock()
    assert human.get_entry("github", "me")["password"] == "gh-secret"


def test_list_metadata_sanitizes_url(tmp_path):
    """OpenAI F8: userinfo/query/fragment never reach metadata."""
    t = str(tmp_path)
    v = _vault(t)
    token = enroll_agent(v, "wright", ["list"])
    s = open_agent_session(v.vault_file, token)
    (meta,) = s.list_metadata()
    assert meta["url"] == "https://github.com/x"
    assert "pw" not in meta["url"] and "token" not in meta["url"]


def test_cli_agent_get_masks_existence(tmp_path):
    """OpenAI F6: missing vs out-of-scope are indistinguishable."""
    t = str(tmp_path)
    v = _vault(t)
    token = enroll_agent(v, "narrow", ["list", "get:gitlab"])
    env = dict(os.environ, MYKEY_AGENT_KEY=token)
    outs = []
    for service in ("github", "nosuchservice"):
        r = subprocess.run(
            [sys.executable, os.path.join(ROOT, "mykey_cli.py"),
             "--vault", v.vault_file, "agent-get", "--service", service],
            capture_output=True, text=True, env=env, timeout=120)
        outs.append((r.returncode, r.stderr.strip(), r.stdout.strip()))
    assert outs[0] == outs[1]
    assert outs[0][0] == 1


@pytest.mark.parametrize("bad", [
    "", "nonsense", "mkag1..", "mkag2.wright.AAAA",
    "mkag1.wright.short", "mkag1.wright." + "A" * 10,
    "mkag1.other." + "A" * 43,
])
def test_malformed_tokens_denied(tmp_path, bad):
    """DeepSeek: parser robustness — every malformed shape denies."""
    t = str(tmp_path)
    v = _vault(t)
    enroll_agent(v, "wright", ["list"])
    with pytest.raises(AgentAuthError):
        open_agent_session(v.vault_file, bad)


def test_scope_with_extra_colon_does_not_widen(tmp_path):
    """DeepSeek: 'get:github:extra' is a scope for a service literally
    named 'github:extra' — it must not grant 'github'."""
    t = str(tmp_path)
    v = _vault(t)
    token = enroll_agent(v, "wright", ["get:github:extra"])
    s = open_agent_session(v.vault_file, token)
    with pytest.raises(AgentScopeError):
        s.get("github")


def test_audit_reorder_detected(tmp_path):
    """DeepSeek: swapping two records breaks the chain."""
    t = str(tmp_path)
    v = _vault(t)
    token = enroll_agent(v, "wright", ["list"])
    open_agent_session(v.vault_file, token)
    open_agent_session(v.vault_file, token)
    audit_file = v.vault_file + ".audit.jsonl"
    with open(audit_file) as f:
        lines = f.read().splitlines()
    assert len(lines) >= 2
    lines[0], lines[1] = lines[1], lines[0]
    with open(audit_file, "w") as f:
        f.write("\n".join(lines) + "\n")
    assert verify_audit(v.vault_file)["ok"] is False


def test_audit_tail_truncation_detected_by_sealed_head(tmp_path):
    """DeepSeek/OpenAI F2: deleting the tail is caught by the seal."""
    t = str(tmp_path)
    v = _vault(t)
    token = enroll_agent(v, "wright", ["list"])
    open_agent_session(v.vault_file, token)
    audit_file = v.vault_file + ".audit.jsonl"
    with open(audit_file) as f:
        lines = f.read().splitlines()
    with open(audit_file, "w") as f:
        f.write("\n".join(lines[:-1]) + "\n")
    assert verify_audit(v.vault_file, expected_head=_head(v))["ok"] is False
